import { spawnSync } from "node:child_process"
import type { AuthoredPlan } from "#/world/town/floorplan/authored-types"

type Props = Readonly<{ plan: AuthoredPlan; filePath: string }>

/** Format before comparing or writing, so a formatter pass cannot turn an unchanged export into a reload. */
export function getAuthoredPlanSource(props: Props): string {
  const source =
    "// Generated by scripts/export-authored-plans.ts; edit the setting documents.\n" +
    'import type { AuthoredPlan } from "#/world/town/floorplan/authored-types"\n' +
    `const plan = ${JSON.stringify(props.plan, null, 2)} satisfies AuthoredPlan\nexport default plan\n`
  const formatted = spawnSync("vp", ["fmt", "--stdin-filepath", props.filePath], { input: source, encoding: "utf8" })
  if (formatted.error) throw formatted.error
  if (formatted.status !== 0) throw new Error(formatted.stderr.trim() || "Authored plan formatting failed")
  return formatted.stdout
}
